/* ================= v5.6: question pools – ≈20 questions per career scene =================
   format per item: {en:[partner,task,model,kw], de:[…], fr:[…], (de_f / fr_f = formal variants for small talk)} */
const ROLEQ={
 intern:[
  {en:["What would you say are your greatest strengths?","Name two strengths with a short proof.","I learn quickly and I'm very organised. In my last semester I combined a part-time job with six exams and still finished with good grades.","learn|organis|organiz|reliable|curious|team|motivat; semester|example|job|project|finished|exams"],
   de:["Was würden Sie als Ihre größten Stärken bezeichnen?","Nenne zwei Stärken mit einem kurzen Beleg.","Ich lerne schnell und bin sehr organisiert. Im letzten Semester habe ich einen Nebenjob mit sechs Prüfungen verbunden und trotzdem gute Noten geschafft.","lerne|organisiert|zuverlässig|neugierig|team|motiviert; semester|beispiel|nebenjob|projekt|prüfung|geschafft"],
   fr:["Quelles sont, selon vous, vos plus grandes qualités ?","Citez deux qualités avec une courte preuve.","J'apprends vite et je suis très organisé. Au dernier semestre, j'ai combiné un job étudiant avec six examens et j'ai quand même obtenu de bonnes notes.","apprends|organisé|fiable|curieux|équipe|motivé; semestre|exemple|job|projet|examens|obtenu"]},
  {en:["How do you react to criticism of your work?","Show that you listen, ask questions and improve.","I listen first and ask what exactly I can do better. Then I use the feedback in the next task – my supervisor's comments on my report made the next one much clearer.","listen|ask|thank|understand; improve|better|use|change|next; example|report|supervisor|last"],
   de:["Wie reagieren Sie auf Kritik an Ihrer Arbeit?","Zeig, dass du zuhörst, nachfragst und dich verbesserst.","Ich höre zuerst zu und frage nach, was ich genau besser machen kann. Dann setze ich das Feedback bei der nächsten Aufgabe um – die Hinweise meines Betreuers zu meinem Bericht haben den nächsten viel klarer gemacht.","höre|frage|danke|verstehe; besser|umsetze|setze|ändere|nächste; beispiel|bericht|betreuer|letzt"],
   fr:["Comment réagissez-vous à la critique de votre travail ?","Montrez que vous écoutez, posez des questions et progressez.","J'écoute d'abord et je demande ce que je peux améliorer exactement. Ensuite, j'applique le retour à la tâche suivante – les remarques de mon encadrant sur mon rapport ont rendu le suivant bien plus clair.","écoute|demande|remercie|comprends; améliorer|applique|mieux|change|suivante; exemple|rapport|encadrant|dernier"]},
  {en:["What do you already know about our company?","Mention two facts and why they interest you.","I know that you make medical devices and that you opened a new research centre last year. I find it motivating to work on products that help patients.","know|read|saw|heard; products|devices|centre|center|company|market|customers; interest|motivat|exciting|because|help"],
   de:["Was wissen Sie bereits über unser Unternehmen?","Nenne zwei Fakten und warum sie dich interessieren.","Ich weiß, dass Sie Medizingeräte herstellen und letztes Jahr ein neues Forschungszentrum eröffnet haben. Es motiviert mich, an Produkten zu arbeiten, die Patienten helfen.","weiß|gelesen|gesehen|gehört; produkt|geräte|zentrum|unternehmen|markt|kunden; interess|motiviert|spannend|weil|helfen"],
   fr:["Que savez-vous déjà de notre entreprise ?","Citez deux faits et pourquoi ils vous intéressent.","Je sais que vous fabriquez des dispositifs médicaux et que vous avez ouvert un nouveau centre de recherche l'an dernier. Travailler sur des produits qui aident les patients me motive.","sais|lu|vu|entendu; produits|dispositifs|centre|entreprise|marché|clients; intéress|motive|passionnant|parce que|aident"]},
  {en:["What role do you usually take in a team?","Describe your typical role with an example.","I'm often the one who keeps the overview – I make the plan and remind everyone of the deadlines. In our robotics club, that helped us finish the robot in time for the competition.","role|usually|often|typically; plan|overview|organis|organiz|coordinat|ideas|support; example|club|project|helped|finish"],
   de:["Welche Rolle übernehmen Sie normalerweise in einem Team?","Beschreibe deine typische Rolle mit einem Beispiel.","Ich bin oft diejenige oder derjenige, die den Überblick behält – ich mache den Plan und erinnere alle an die Termine. In unserem Robotik-Club hat uns das geholfen, den Roboter rechtzeitig zum Wettbewerb fertigzustellen.","rolle|oft|normalerweise|meistens; plan|überblick|organisier|koordinier|ideen|unterstütz; beispiel|club|projekt|geholfen|fertig"],
   fr:["Quel rôle prenez-vous habituellement dans une équipe ?","Décrivez votre rôle habituel avec un exemple.","Je suis souvent celui ou celle qui garde la vue d'ensemble – je fais le planning et je rappelle les échéances à tout le monde. Dans notre club de robotique, cela nous a aidés à finir le robot à temps pour la compétition.","rôle|souvent|habituellement|généralement; planning|vue d'ensemble|organis|coordonn|idées|soutien; exemple|club|projet|aidé|finir"]},
  {en:["How do you organise your time between studies and other commitments?","Explain your method briefly.","I plan my week every Sunday: fixed times for lectures, studying and work, and one free evening. I use a simple to-do list and do the most important task first each day.","plan|week|schedule|calendar|list; priorit|important|first|fixed|times; work|study|lectures|free|balance"],
   de:["Wie organisieren Sie Ihre Zeit zwischen Studium und anderen Verpflichtungen?","Erkläre kurz deine Methode.","Ich plane jeden Sonntag meine Woche: feste Zeiten für Vorlesungen, Lernen und Arbeit und einen freien Abend. Ich nutze eine einfache Aufgabenliste und erledige jeden Tag zuerst das Wichtigste.","plane|woche|kalender|liste|zeitplan; wichtig|zuerst|feste|zeiten|priorit; arbeit|lernen|vorlesung|frei|ausgleich"],
   fr:["Comment organisez-vous votre temps entre les études et vos autres engagements ?","Expliquez brièvement votre méthode.","Je planifie ma semaine chaque dimanche : des créneaux fixes pour les cours, les révisions et le travail, et une soirée libre. J'utilise une simple liste de tâches et je fais d'abord la tâche la plus importante chaque jour.","planifie|semaine|agenda|liste|planning; important|d'abord|fixes|créneaux|priorit; travail|révisions|cours|libre|équilibre"]},
  {en:["What would you like to learn during this internship?","Name concrete skills or experiences.","I'd like to learn how a real development project is managed from the first idea to the product. I'd also like to improve my CAD skills and get to know how customers are involved.","learn|improve|understand|experience|get to know; project|development|product|skills|cad|customers|team; how|real|practice|from"],
   de:["Was möchten Sie in diesem Praktikum lernen?","Nenne konkrete Fähigkeiten oder Erfahrungen.","Ich möchte lernen, wie ein echtes Entwicklungsprojekt von der ersten Idee bis zum Produkt gesteuert wird. Außerdem möchte ich meine CAD-Kenntnisse verbessern und sehen, wie Kunden einbezogen werden.","lernen|verbessern|verstehen|erfahrung|kennenlernen|sehen; projekt|entwicklung|produkt|kenntnisse|cad|kunden|team; wie|echt|praxis|von"],
   fr:["Qu'aimeriez-vous apprendre pendant ce stage ?","Citez des compétences ou expériences concrètes.","J'aimerais apprendre comment un vrai projet de développement est mené de la première idée jusqu'au produit. J'aimerais aussi améliorer mes compétences en CAO et voir comment les clients sont impliqués.","apprendre|améliorer|comprendre|expérience|découvrir|voir; projet|développement|produit|compétences|cao|clients|équipe; comment|vrai|pratique"]},
  {en:["Tell me about something you taught yourself.","Describe what, how and why.","Last year I taught myself Python with online courses, because I wanted to analyse the data from my lab experiments faster. Now I automate most of my evaluations.","taught|learned|learnt|myself|self; online|course|book|videos|practice|python|language|tool; because|wanted|now|faster|use"],
   de:["Erzählen Sie von etwas, das Sie sich selbst beigebracht haben.","Beschreibe was, wie und warum.","Letztes Jahr habe ich mir mit Online-Kursen Python beigebracht, weil ich die Daten aus meinen Laborversuchen schneller auswerten wollte. Heute automatisiere ich die meisten Auswertungen.","beigebracht|gelernt|selbst; online|kurs|buch|videos|übung|python|sprache|werkzeug; weil|wollte|heute|schneller|nutze"],
   fr:["Parlez-moi de quelque chose que vous avez appris par vous-même.","Décrivez quoi, comment et pourquoi.","L'an dernier, j'ai appris Python seul avec des cours en ligne, parce que je voulais analyser plus vite les données de mes expériences de labo. Aujourd'hui, j'automatise la plupart de mes analyses.","appris|seul|moi-même|autodidacte; en ligne|cours|livre|vidéos|pratique|python|langue|outil; parce que|voulais|aujourd'hui|plus vite|utilise"]}],
 grad:[
  {en:["Why did you choose this industry?","Give a personal and a professional reason.","I've been fascinated by renewable energy since a school project on wind power. Professionally, it's a growing industry where engineers can have a real impact.","fascinat|interest|passion|always|since; energy|industry|sector|field|technology; growing|future|impact|important|because"],
   de:["Warum haben Sie sich für diese Branche entschieden?","Nenne einen persönlichen und einen beruflichen Grund.","Erneuerbare Energien faszinieren mich seit einem Schulprojekt zur Windkraft. Beruflich ist es eine wachsende Branche, in der Ingenieurinnen und Ingenieure wirklich etwas bewegen können.","fasziniert|interess|begeister|schon immer|seit; energie|branche|bereich|technik; wachsend|zukunft|bewegen|wichtig|weil"],
   fr:["Pourquoi avez-vous choisi ce secteur ?","Donnez une raison personnelle et une raison professionnelle.","Les énergies renouvelables me fascinent depuis un projet scolaire sur l'éolien. Sur le plan professionnel, c'est un secteur en croissance où les ingénieurs peuvent avoir un vrai impact.","fascin|intéress|passion|toujours|depuis; énergie|secteur|domaine|technologie; croissance|avenir|impact|important|parce que"]},
  {en:["What achievement are you most proud of?","Describe the achievement and your contribution.","I'm most proud of winning a university innovation prize with my team. I developed the prototype and presented it to the jury, which taught me a lot about explaining ideas simply.","proud|achievement|won|prize|award|finished|managed; developed|built|led|presented|my part|i; learned|learnt|taught|result"],
   de:["Auf welche Leistung sind Sie besonders stolz?","Beschreibe die Leistung und deinen Beitrag.","Am meisten stolz bin ich auf einen Innovationspreis der Hochschule, den ich mit meinem Team gewonnen habe. Ich habe den Prototyp entwickelt und ihn der Jury vorgestellt – dabei habe ich viel darüber gelernt, Ideen einfach zu erklären.","stolz|leistung|gewonnen|preis|geschafft; entwickelt|gebaut|geleitet|vorgestellt|mein beitrag|ich habe; gelernt|ergebnis"],
   fr:["De quelle réussite êtes-vous le plus fier ?","Décrivez la réussite et votre contribution.","Je suis surtout fier d'avoir gagné un prix d'innovation universitaire avec mon équipe. J'ai développé le prototype et je l'ai présenté au jury, ce qui m'a beaucoup appris sur l'art d'expliquer simplement une idée.","fier|réussite|gagné|prix|réussi; développé|construit|dirigé|présenté|ma part|j'ai; appris|résultat"]},
  {en:["Describe a situation where you had to adapt quickly.","Show flexibility and a positive result.","During my exchange semester in Lyon, all lectures were suddenly in French. I took an intensive course, formed a study group with local students and passed all my exams.","exchange|abroad|new|sudden|change|situation; adapt|course|learned|organised|organized|asked|group; passed|result|finally|managed|success"],
   de:["Beschreiben Sie eine Situation, in der Sie sich schnell anpassen mussten.","Zeig Flexibilität und ein positives Ergebnis.","In meinem Auslandssemester in Lyon fanden alle Vorlesungen plötzlich auf Französisch statt. Ich habe einen Intensivkurs belegt, eine Lerngruppe mit einheimischen Studierenden gebildet und alle Prüfungen bestanden.","ausland|neu|plötzlich|veränderung|situation; angepasst|kurs|gelernt|organisiert|gefragt|gruppe; bestanden|ergebnis|geschafft|erfolg"],
   fr:["Décrivez une situation où vous avez dû vous adapter rapidement.","Montrez votre flexibilité et un résultat positif.","Pendant mon semestre d'échange à Lyon, tous les cours étaient soudain en français. J'ai suivi un cours intensif, formé un groupe de travail avec des étudiants locaux et réussi tous mes examens.","échange|étranger|nouveau|soudain|changement|situation; adapté|cours|appris|organisé|demandé|groupe; réussi|résultat|finalement|succès"]},
  {en:["What are your salary expectations?","Give a realistic range and stay open.","Based on my research for graduate positions in this region, I'm thinking of a range between fifty and fifty-five thousand euros. But the development opportunities are just as important to me.","research|based on|market|region|typical; range|between|thousand|euros|salary; open|important|development|opportunit|flexible"],
   de:["Welche Gehaltsvorstellungen haben Sie?","Nenne eine realistische Spanne und bleib offen.","Nach meiner Recherche für Einstiegspositionen in dieser Region denke ich an eine Spanne zwischen fünfzig- und fünfundfünfzigtausend Euro. Die Entwicklungsmöglichkeiten sind mir aber genauso wichtig.","recherche|markt|region|üblich|nach; spanne|zwischen|tausend|euro|gehalt; offen|wichtig|entwicklung|möglichkeit|flexibel"],
   fr:["Quelles sont vos prétentions salariales ?","Donnez une fourchette réaliste et restez ouvert.","D'après mes recherches sur les postes de jeunes diplômés dans la région, je pense à une fourchette entre quarante-cinq et cinquante mille euros. Mais les perspectives d'évolution comptent tout autant pour moi.","recherches|d'après|marché|région|habituel; fourchette|entre|mille|euros|salaire; ouvert|important|évolution|perspectives|comptent"]},
  {en:["Tell me about a time you took the lead.","Describe the situation, what you did and the result.","When our group project stalled, I suggested splitting the work into weekly goals and led a short meeting every Monday. We finished two days early and got the best grade in the course.","project|group|team|situation|stalled|problem; suggested|led|organised|organized|took|meeting|goals; finished|result|grade|early|success"],
   de:["Erzählen Sie von einer Situation, in der Sie die Führung übernommen haben.","Beschreibe die Situation, was du getan hast und das Ergebnis.","Als unser Gruppenprojekt ins Stocken geriet, habe ich vorgeschlagen, die Arbeit in Wochenziele aufzuteilen, und jeden Montag ein kurzes Treffen geleitet. Wir waren zwei Tage früher fertig und hatten die beste Note im Kurs.","projekt|gruppe|team|situation|stocken|problem; vorgeschlagen|geleitet|organisiert|übernommen|treffen|ziele; fertig|ergebnis|note|früher|erfolg"],
   fr:["Parlez-moi d'une situation où vous avez pris les choses en main.","Décrivez la situation, ce que vous avez fait et le résultat.","Quand notre projet de groupe s'est enlisé, j'ai proposé de découper le travail en objectifs hebdomadaires et j'ai animé une courte réunion chaque lundi. Nous avons fini deux jours en avance avec la meilleure note du cours.","projet|groupe|équipe|situation|enlisé|problème; proposé|animé|organisé|pris|réunion|objectifs; fini|résultat|note|avance|succès"]},
  {en:["How do you deal with pressure, for example before exams?","Name your strategy and an example.","I break big tasks into small steps and start early. Before my final exams I made a revision plan for six weeks, which kept me calm even when things got busy.","pressure|stress|exams|deadline; break|steps|plan|early|start|priorit|sport|calm; example|weeks|kept|worked|before"],
   de:["Wie gehen Sie mit Druck um, zum Beispiel vor Prüfungen?","Nenne deine Strategie und ein Beispiel.","Ich zerlege große Aufgaben in kleine Schritte und fange früh an. Vor meinen Abschlussprüfungen habe ich einen Lernplan für sechs Wochen gemacht, der mich auch in stressigen Phasen ruhig gehalten hat.","druck|stress|prüfung|termin; zerlege|schritte|plan|früh|anfange|fange|priorit|sport|ruhig; beispiel|wochen|gehalten|geholfen|vor"],
   fr:["Comment gérez-vous la pression, par exemple avant les examens ?","Citez votre stratégie et un exemple.","Je découpe les grandes tâches en petites étapes et je commence tôt. Avant mes examens finaux, j'ai fait un planning de révision sur six semaines, qui m'a gardé calme même dans les périodes chargées.","pression|stress|examens|échéance; découpe|étapes|planning|tôt|commence|priorit|sport|calme; exemple|semaines|gardé|aidé|avant"]},
  {en:["How do you keep learning after university?","Name concrete ways to keep developing.","I read two technical newsletters every week and I'm doing an online certificate in project management. I also learn a lot from experienced colleagues by asking questions.","read|newsletter|articles|books|podcast|courses|certificate|online; colleagues|mentor|ask|questions|conferences; every|week|regularly|currently|now"],
   de:["Wie lernen Sie nach dem Studium weiter?","Nenne konkrete Wege, dich weiterzuentwickeln.","Ich lese jede Woche zwei Fach-Newsletter und mache gerade ein Online-Zertifikat in Projektmanagement. Außerdem lerne ich viel von erfahrenen Kollegen, indem ich Fragen stelle.","lese|newsletter|artikel|bücher|podcast|kurs|zertifikat|online; kollegen|mentor|frage|fragen|konferenz; jede|woche|regelmäßig|gerade|aktuell"],
   fr:["Comment continuez-vous à apprendre après l'université ?","Citez des moyens concrets de progresser.","Je lis deux newsletters techniques chaque semaine et je suis en train de passer un certificat en ligne en gestion de projet. J'apprends aussi beaucoup des collègues expérimentés en posant des questions.","lis|newsletter|articles|livres|podcast|cours|certificat|en ligne; collègues|mentor|questions|conférences; chaque|semaine|régulièrement|en train"]}],
 eng:[
  {en:["How would you explain your design to a customer without technical background?","Use the benefit for the customer and a simple comparison.","I would start with what it means for them: the new pump uses a third less energy. Then I'd compare it to a car that automatically drives more economically in city traffic.","customer|benefit|means|for them|save|energy|cost; compare|like|similar|simple|example; start|first|then"],
   de:["Wie würden Sie Ihre Konstruktion einem Kunden ohne technischen Hintergrund erklären?","Nutze den Nutzen für den Kunden und einen einfachen Vergleich.","Ich würde mit dem beginnen, was es für ihn bedeutet: Die neue Pumpe braucht ein Drittel weniger Energie. Dann würde ich sie mit einem Auto vergleichen, das im Stadtverkehr automatisch sparsamer fährt.","kunde|nutzen|bedeutet|spart|energie|kosten|weniger; vergleich|wie|ähnlich|einfach|beispiel; beginnen|zuerst|dann"],
   fr:["Comment expliqueriez-vous votre conception à un client sans formation technique ?","Partez du bénéfice client et d'une comparaison simple.","Je commencerais par ce que cela change pour lui : la nouvelle pompe consomme un tiers d'énergie en moins. Puis je la comparerais à une voiture qui roule automatiquement plus économiquement en ville.","client|bénéfice|change|économ|énergie|coût|moins; compar|comme|simple|exemple; commencerais|d'abord|puis"]},
  {en:["How do you find the root cause of a technical failure?","Name your method step by step.","I collect the facts first: data, photos and the operating history. Then I use the five-whys method or a fishbone diagram with the team, test the most likely cause and only then define the fix.","facts|data|collect|history|photos|evidence; five whys|5 why|fishbone|ishikawa|analysis|team|method; test|verify|cause|fix|measure|then"],
   de:["Wie finden Sie die Ursache eines technischen Fehlers?","Nenne deine Methode Schritt für Schritt.","Zuerst sammle ich die Fakten: Daten, Fotos und den Betriebsverlauf. Dann nutze ich mit dem Team die Fünf-Warum-Methode oder ein Ishikawa-Diagramm, prüfe die wahrscheinlichste Ursache und lege erst dann die Abhilfe fest.","fakten|daten|sammle|verlauf|fotos|belege; warum|ishikawa|fischgräten|analyse|team|methode; prüfe|teste|ursache|abhilfe|maßnahme|dann"],
   fr:["Comment trouvez-vous la cause racine d'une défaillance technique ?","Citez votre méthode étape par étape.","Je rassemble d'abord les faits : données, photos et historique de fonctionnement. Ensuite, j'utilise avec l'équipe la méthode des cinq pourquoi ou un diagramme d'Ishikawa, je teste la cause la plus probable et seulement ensuite je définis la correction.","faits|données|rassemble|historique|photos|preuves; pourquoi|ishikawa|analyse|équipe|méthode; teste|vérifie|cause|correction|mesure|ensuite"]},
  {en:["Which standards or regulations do you work with?","Name them and say how you apply them.","I mainly work with the Machinery Directive and the relevant ISO standards for safety. I check them at the start of each project and document how every requirement is met.","directive|standard|iso|norm|regulation|din|en|iec; check|apply|use|follow|start|project; document|requirement|met|compliance|evidence"],
   de:["Mit welchen Normen oder Vorschriften arbeiten Sie?","Nenne sie und sag, wie du sie anwendest.","Ich arbeite vor allem mit der Maschinenrichtlinie und den einschlägigen ISO-Normen zur Sicherheit. Ich prüfe sie zu Beginn jedes Projekts und dokumentiere, wie jede Anforderung erfüllt wird.","richtlinie|norm|iso|din|vorschrift|iec; prüfe|wende|anwend|nutze|beginn|projekt; dokumentier|anforderung|erfüllt|nachweis"],
   fr:["Avec quelles normes ou réglementations travaillez-vous ?","Citez-les et dites comment vous les appliquez.","Je travaille surtout avec la directive Machines et les normes ISO de sécurité correspondantes. Je les vérifie au début de chaque projet et je documente comment chaque exigence est respectée.","directive|norme|iso|réglementation|iec; vérifie|applique|utilise|suis|début|projet; document|exigence|respectée|conformité|preuve"]},
  {en:["How do you balance cost and quality?","Show a clear priority and an example.","Safety and the agreed quality are never negotiable. Within that, I look for the cheapest solution – for example, we changed a machined part to a cast part and saved twenty percent without losing strength.","safety|quality|never|negotiable|requirement; cost|cheap|save|saved|price|budget; example|changed|percent|without"],
   de:["Wie wägen Sie zwischen Kosten und Qualität ab?","Zeig eine klare Priorität und ein Beispiel.","Sicherheit und die vereinbarte Qualität sind nie verhandelbar. Innerhalb dessen suche ich die günstigste Lösung – zum Beispiel haben wir ein Frästeil durch ein Gussteil ersetzt und zwanzig Prozent gespart, ohne an Festigkeit zu verlieren.","sicherheit|qualität|nie|verhandelbar|anforderung; kosten|günstig|gespart|preis|budget; beispiel|ersetzt|prozent|ohne"],
   fr:["Comment arbitrez-vous entre coût et qualité ?","Montrez une priorité claire et un exemple.","La sécurité et la qualité convenue ne sont jamais négociables. Dans ce cadre, je cherche la solution la moins chère – par exemple, nous avons remplacé une pièce usinée par une pièce moulée et économisé vingt pour cent sans perdre en résistance.","sécurité|qualité|jamais|négociable|exigence; coût|moins chère|économisé|prix|budget; exemple|remplacé|pour cent|sans"]},
  {en:["How do you estimate how long a task will take?","Explain your estimation method.","I break the task into small work packages, estimate each one from past projects and add a buffer for risks. I also ask the colleagues who will do the work, because they know the details best.","break|packages|steps|small|split; past|experience|previous|data|history; buffer|risk|ask|colleagues|team|details"],
   de:["Wie schätzen Sie ab, wie lange eine Aufgabe dauert?","Erkläre deine Schätzmethode.","Ich zerlege die Aufgabe in kleine Arbeitspakete, schätze jedes anhand früherer Projekte und plane einen Puffer für Risiken ein. Außerdem frage ich die Kollegen, die die Arbeit machen, weil sie die Details am besten kennen.","zerlege|pakete|schritte|klein|aufteil; früher|erfahrung|vorherig|daten; puffer|risik|frage|kollegen|team|details"],
   fr:["Comment estimez-vous la durée d'une tâche ?","Expliquez votre méthode d'estimation.","Je découpe la tâche en petits lots de travail, j'estime chacun d'après des projets passés et j'ajoute une marge pour les risques. Je demande aussi aux collègues qui feront le travail, car ce sont eux qui connaissent le mieux les détails.","découpe|lots|étapes|petits; passés|expérience|précédents|données; marge|risque|demande|collègues|équipe|détails"]},
  {en:["How important is documentation for you?","Give your view and a practical habit.","Very important – good documentation saves time when someone else continues the work. I write a short decision log for every design change, so we always know why something was done.","important|essential|very|crucial; saves|time|someone else|team|later|continue; log|write|record|decision|change|why"],
   de:["Wie wichtig ist Ihnen Dokumentation?","Nenne deine Haltung und eine praktische Gewohnheit.","Sehr wichtig – eine gute Dokumentation spart Zeit, wenn jemand anderes die Arbeit fortsetzt. Ich schreibe zu jeder Konstruktionsänderung ein kurzes Entscheidungsprotokoll, damit wir immer wissen, warum etwas gemacht wurde.","wichtig|wesentlich|sehr|entscheidend; spart|zeit|jemand|team|später|fortsetzt; protokoll|schreibe|festhalte|entscheidung|änderung|warum"],
   fr:["Quelle importance accordez-vous à la documentation ?","Donnez votre avis et une habitude concrète.","Très importante – une bonne documentation fait gagner du temps quand quelqu'un d'autre reprend le travail. Je tiens un court journal de décisions pour chaque modification de conception, pour qu'on sache toujours pourquoi quelque chose a été fait.","important|essentiel|très|cruciale; gagner|temps|quelqu'un|équipe|plus tard|reprend; journal|écris|note|décision|modification|pourquoi"]},
  {en:["How do you work with suppliers when there is a quality problem?","Show facts, partnership and a clear agreement.","I share the measurement data with the supplier quickly and visit them if needed. We agree on an action plan with clear deadlines and check the next deliveries closely until the problem is solved.","data|measurement|facts|evidence|share; supplier|visit|together|partner|call|meeting; action plan|deadline|agree|check|deliveries|solved"],
   de:["Wie arbeiten Sie mit Lieferanten zusammen, wenn es ein Qualitätsproblem gibt?","Zeig Fakten, Partnerschaft und eine klare Vereinbarung.","Ich teile die Messdaten schnell mit dem Lieferanten und besuche ihn bei Bedarf. Wir vereinbaren einen Maßnahmenplan mit klaren Terminen und prüfen die nächsten Lieferungen genau, bis das Problem gelöst ist.","daten|mess|fakten|belege|teile; lieferant|besuche|gemeinsam|partner|anruf|treffen; maßnahmen|termin|vereinbar|prüfen|lieferung|gelöst"],
   fr:["Comment travaillez-vous avec les fournisseurs en cas de problème de qualité ?","Montrez faits, partenariat et accord clair.","Je partage rapidement les données de mesure avec le fournisseur et je me rends sur place si nécessaire. Nous convenons d'un plan d'action avec des délais clairs et nous contrôlons de près les livraisons suivantes jusqu'à ce que le problème soit résolu.","données|mesure|faits|preuves|partage; fournisseur|sur place|ensemble|partenaire|appel|réunion; plan d'action|délai|convenons|contrôl|livraisons|résolu"]}],
 senior:[
  {en:["How do you deal with technical debt in a project?","Show that you make it visible and plan it.","I make technical debt visible in the backlog with its risk and cost. Then I agree with the product owner to reserve about fifteen percent of each sprint for it, starting with the riskiest items.","visible|backlog|list|track|document; risk|cost|impact|priorit; reserve|percent|sprint|plan|agree|time"],
   de:["Wie gehen Sie mit technischen Schulden in einem Projekt um?","Zeig, dass du sie sichtbar machst und einplanst.","Ich mache technische Schulden im Backlog sichtbar, mit Risiko und Kosten. Dann vereinbare ich mit dem Product Owner, etwa fünfzehn Prozent jedes Sprints dafür zu reservieren – angefangen mit den riskantesten Punkten.","sichtbar|backlog|liste|dokumentier|erfass; risiko|kosten|auswirkung|priorit; reservier|prozent|sprint|plan|vereinbar|zeit"],
   fr:["Comment gérez-vous la dette technique dans un projet ?","Montrez que vous la rendez visible et la planifiez.","Je rends la dette technique visible dans le backlog avec son risque et son coût. Ensuite, je conviens avec le product owner de réserver environ quinze pour cent de chaque sprint, en commençant par les points les plus risqués.","visible|backlog|liste|document|suivi; risque|coût|impact|priorit; réserver|pour cent|sprint|planifi|convien|temps"]},
  {en:["How do you influence people you have no authority over?","Name your approach with an example.","I build trust first and show what's in it for them. To get the production team to adopt a new test step, I involved their shift leaders in the design and showed data that it reduced rework.","trust|relationship|listen|understand; benefit|in it for them|data|show|involve|involved; example|team|adopt|reduced|convinced|result"],
   de:["Wie beeinflussen Sie Menschen, denen Sie nicht vorgesetzt sind?","Nenne deinen Ansatz mit einem Beispiel.","Ich baue zuerst Vertrauen auf und zeige, was es ihnen bringt. Damit die Produktion einen neuen Prüfschritt übernimmt, habe ich ihre Schichtleiter in die Gestaltung einbezogen und mit Daten gezeigt, dass er Nacharbeit reduziert.","vertrauen|beziehung|zuhören|verstehen; nutzen|bringt|daten|zeige|einbezogen|beteilig; beispiel|team|übernimmt|reduziert|überzeugt|ergebnis"],
   fr:["Comment influencez-vous des personnes sur lesquelles vous n'avez pas d'autorité ?","Citez votre approche avec un exemple.","Je construis d'abord la confiance et je montre ce qu'ils y gagnent. Pour que la production adopte une nouvelle étape de contrôle, j'ai associé les chefs d'équipe à la conception et montré par des données qu'elle réduisait les reprises.","confiance|relation|écoute|comprendre; gagnent|bénéfice|données|montre|associé|impliqu; exemple|équipe|adopte|réduisait|convaincu|résultat"]},
  {en:["What do you look for when you hire engineers?","Name a few criteria and how you test them.","Besides solid fundamentals, I look for curiosity and the ability to explain their work. In interviews I ask them to walk me through a problem they solved and to tell me what they would do differently today.","fundamentals|skills|knowledge|technical; curiosity|curious|explain|communicat|team|attitude; interview|ask|walk me through|problem|differently"],
   de:["Worauf achten Sie, wenn Sie Ingenieure einstellen?","Nenne einige Kriterien und wie du sie prüfst.","Neben soliden Grundlagen achte ich auf Neugier und die Fähigkeit, die eigene Arbeit zu erklären. Im Gespräch lasse ich mir ein gelöstes Problem schildern und frage, was sie heute anders machen würden.","grundlagen|fachwissen|kenntnisse|technisch; neugier|erklären|kommunikat|team|haltung; gespräch|frage|schildern|problem|anders"],
   fr:["Que recherchez-vous quand vous recrutez des ingénieurs ?","Citez quelques critères et comment vous les testez.","Au-delà de bases solides, je cherche la curiosité et la capacité à expliquer son travail. En entretien, je leur demande de me décrire un problème qu'ils ont résolu et ce qu'ils feraient différemment aujourd'hui.","bases|compétences|connaissances|technique; curiosité|expliquer|communic|équipe|attitude; entretien|demande|décrire|problème|différemment"]},
  {en:["Tell me about a critical incident you had to manage.","Describe immediate actions, communication and lessons.","A line stopped at a major customer on a Friday night. I set up a call within an hour, got a temporary fix running by morning, informed the customer every two hours, and afterwards we introduced an early-warning alarm.","incident|stopped|failure|outage|critical|night; call|team|fix|temporary|immediately|hour; informed|customer|communicat|afterwards|lesson|introduced|alarm"],
   de:["Erzählen Sie von einem kritischen Störfall, den Sie bewältigen mussten.","Beschreibe Sofortmaßnahmen, Kommunikation und Lehren.","Bei einem wichtigen Kunden stand an einem Freitagabend eine Linie still. Innerhalb einer Stunde habe ich eine Telefonkonferenz aufgesetzt, bis zum Morgen lief eine Übergangslösung, ich habe den Kunden alle zwei Stunden informiert, und danach haben wir einen Frühwarnalarm eingeführt.","störfall|stillstand|stand|ausfall|kritisch|abend; telefon|team|lösung|übergang|sofort|stunde; informiert|kunde|kommunizier|danach|lehre|eingeführt|alarm"],
   fr:["Parlez-moi d'un incident critique que vous avez dû gérer.","Décrivez les actions immédiates, la communication et les leçons.","Une ligne s'est arrêtée chez un client important un vendredi soir. J'ai organisé une conférence téléphonique en moins d'une heure, une solution provisoire tournait le matin, j'ai informé le client toutes les deux heures, puis nous avons mis en place une alarme précoce.","incident|arrêtée|panne|critique|soir; conférence|équipe|solution|provisoire|immédiat|heure; informé|client|communiqu|puis|leçon|mis en place|alarme"]},
  {en:["How do you encourage innovation in your team?","Name concrete practices.","I give the team time for small experiments – one afternoon a month – and we present the results to each other. Good ideas get a sponsor and a budget, and failed experiments are discussed openly without blame.","time|experiments|afternoon|hackathon|ideas; present|share|results|sponsor|budget; fail|failed|openly|blame|safe|learn"],
   de:["Wie fördern Sie Innovation in Ihrem Team?","Nenne konkrete Praktiken.","Ich gebe dem Team Zeit für kleine Experimente – einen Nachmittag im Monat – und wir stellen uns die Ergebnisse gegenseitig vor. Gute Ideen bekommen einen Paten und ein Budget, und gescheiterte Versuche besprechen wir offen und ohne Schuldzuweisung.","zeit|experiment|nachmittag|hackathon|ideen; vorstellen|teilen|ergebnis|pate|budget; gescheitert|offen|schuld|sicher|lernen"],
   fr:["Comment encouragez-vous l'innovation dans votre équipe ?","Citez des pratiques concrètes.","Je donne à l'équipe du temps pour de petites expériences – un après-midi par mois – et nous nous présentons les résultats. Les bonnes idées reçoivent un parrain et un budget, et les échecs sont discutés ouvertement, sans reproche.","temps|expérience|après-midi|hackathon|idées; présent|partage|résultats|parrain|budget; échec|ouvertement|reproche|confiance|apprendre"]},
  {en:["How do you make collaboration work across different sites or countries?","Name tools, rhythms and cultural aspects.","We have a short weekly video meeting at a time that works for everyone, one shared task board and clear owners. I also visit the other sites twice a year, because personal contact builds trust.","weekly|meeting|video|call|rhythm|regular; board|tool|shared|owners|clear|document; visit|personal|culture|trust|time zone"],
   de:["Wie gelingt Ihnen die Zusammenarbeit über verschiedene Standorte oder Länder hinweg?","Nenne Werkzeuge, Rhythmen und kulturelle Aspekte.","Wir haben ein kurzes wöchentliches Videomeeting zu einer Zeit, die für alle passt, ein gemeinsames Aufgabenboard und klare Verantwortliche. Außerdem besuche ich die anderen Standorte zweimal im Jahr, weil persönlicher Kontakt Vertrauen schafft.","wöchentlich|meeting|video|rhythmus|regelmäßig; board|werkzeug|gemeinsam|verantwortlich|klar; besuche|persönlich|kultur|vertrauen|zeitzone"],
   fr:["Comment réussissez-vous la collaboration entre différents sites ou pays ?","Citez outils, rythmes et aspects culturels.","Nous avons une courte visio hebdomadaire à une heure qui convient à tous, un tableau de tâches commun et des responsables clairs. Je me rends aussi sur les autres sites deux fois par an, car le contact personnel crée la confiance.","hebdomadaire|réunion|visio|rythme|régulier; tableau|outil|commun|responsables|clair; rends|visite|personnel|culture|confiance|fuseau"]},
  {en:["How do you review an architecture or design proposal?","Describe your review criteria.","I check it against the requirements first, then look at risks, interfaces and how easy it is to test and maintain. I ask the author to explain the alternatives they rejected – that usually shows how solid the proposal is.","requirements|requirement|criteria|check; risk|interface|test|maintain|scalab|safety|cost; alternative|rejected|ask|author|explain|why"],
   de:["Wie prüfen Sie einen Architektur- oder Konstruktionsvorschlag?","Beschreibe deine Prüfkriterien.","Ich prüfe ihn zuerst gegen die Anforderungen, dann schaue ich auf Risiken, Schnittstellen und darauf, wie gut er sich testen und warten lässt. Ich bitte den Autor, die verworfenen Alternativen zu erklären – das zeigt meist, wie solide der Vorschlag ist.","anforderung|kriterien|prüfe; risik|schnittstelle|test|wart|skalier|sicherheit|kosten; alternative|verworfen|bitte|autor|erklären|warum"],
   fr:["Comment évaluez-vous une proposition d'architecture ou de conception ?","Décrivez vos critères de revue.","Je la vérifie d'abord par rapport aux exigences, puis j'examine les risques, les interfaces et la facilité de test et de maintenance. Je demande à l'auteur d'expliquer les alternatives écartées – cela montre souvent la solidité de la proposition.","exigences|critères|vérifie; risque|interface|test|maintenance|évolutiv|sécurité|coût; alternative|écartées|demande|auteur|expliquer|pourquoi"]}],
 lawyer:[
  {en:["How do you approach a legal due diligence?","Describe the main steps.","I start with a clear scope and a checklist with the client: contracts, litigation, employment and intellectual property. Then the team reviews the data room, flags the risks by priority and summarises them in a short red-flag report.","scope|checklist|client|agree|start; contracts|litigation|employment|ip|intellectual|data room|review; risk|flag|priorit|report|summar"],
   de:["Wie gehen Sie bei einer rechtlichen Due Diligence vor?","Beschreibe die wichtigsten Schritte.","Ich beginne mit einem klaren Umfang und einer Checkliste, abgestimmt mit dem Mandanten: Verträge, Rechtsstreitigkeiten, Arbeitsrecht und geistiges Eigentum. Dann prüft das Team den Datenraum, markiert die Risiken nach Priorität und fasst sie in einem kurzen Red-Flag-Bericht zusammen.","umfang|checkliste|mandant|abgestimmt|beginne; verträge|rechtsstreit|arbeitsrecht|geistiges|datenraum|prüft; risik|markiert|priorit|bericht|zusammen"],
   fr:["Comment abordez-vous un audit juridique (due diligence) ?","Décrivez les principales étapes.","Je commence par un périmètre clair et une liste de contrôle convenue avec le client : contrats, contentieux, droit social et propriété intellectuelle. Ensuite, l'équipe examine la data room, signale les risques par priorité et les résume dans un court rapport des points rouges.","périmètre|liste|client|convenue|commence; contrats|contentieux|social|propriété|data room|examine; risque|signale|priorit|rapport|résume"]},
  {en:["How do you negotiate a difficult clause with the other side?","Show preparation, interests and options.","I prepare our fallback positions with the client beforehand. In the negotiation I ask about the interest behind their wording, and then offer options – for example a liability cap instead of a full exclusion.","prepare|preparation|fallback|position|beforehand|client; interest|why|ask|understand|behind; option|offer|alternative|cap|instead|compromise"],
   de:["Wie verhandeln Sie eine schwierige Klausel mit der Gegenseite?","Zeig Vorbereitung, Interessen und Optionen.","Ich bereite vorher mit dem Mandanten unsere Rückfallpositionen vor. In der Verhandlung frage ich nach dem Interesse hinter ihrer Formulierung und biete dann Optionen an – zum Beispiel eine Haftungsobergrenze statt eines vollständigen Ausschlusses.","vorbereit|rückfall|position|vorher|mandant; interesse|warum|frage|verstehen|hinter; option|biete|alternative|obergrenze|statt|kompromiss"],
   fr:["Comment négociez-vous une clause difficile avec la partie adverse ?","Montrez préparation, intérêts et options.","Je prépare à l'avance nos positions de repli avec le client. Pendant la négociation, je demande quel intérêt se cache derrière leur formulation, puis je propose des options – par exemple un plafond de responsabilité au lieu d'une exclusion totale.","prépare|repli|position|avance|client; intérêt|pourquoi|demande|comprendre|derrière; option|propose|alternative|plafond|au lieu|compromis"]},
  {en:["How do you stay up to date with changes in the law?","Name your sources and routine.","I follow the official gazette and two specialist journals, and I'm in a working group of my bar association. Every Friday I take half an hour to read new court decisions in my field.","journal|gazette|newsletter|database|sources|read; working group|association|seminar|conference|colleagues; every|week|friday|routine|decisions|court"],
   de:["Wie bleiben Sie bei Gesetzesänderungen auf dem Laufenden?","Nenne deine Quellen und deine Routine.","Ich verfolge das Bundesgesetzblatt und zwei Fachzeitschriften und bin in einem Arbeitskreis meiner Kammer. Jeden Freitag nehme ich mir eine halbe Stunde, um neue Urteile in meinem Rechtsgebiet zu lesen.","zeitschrift|gesetzblatt|newsletter|datenbank|quellen|lese; arbeitskreis|kammer|seminar|konferenz|kollegen; jeden|woche|freitag|routine|urteile|gericht"],
   fr:["Comment vous tenez-vous informé des évolutions du droit ?","Citez vos sources et votre routine.","Je suis le Journal officiel et deux revues spécialisées, et je participe à un groupe de travail de mon barreau. Chaque vendredi, je prends une demi-heure pour lire les nouvelles décisions dans mon domaine.","journal|revue|newsletter|base|sources|lis; groupe de travail|barreau|séminaire|conférence|confrères; chaque|semaine|vendredi|routine|décisions|jurisprudence"]},
  {en:["What would you do if you noticed a possible conflict of interest?","Show that you act immediately and transparently.","I would stop working on the matter, check it with our conflict system and inform the responsible partner straight away. If there is a conflict, we decline or get the informed consent of both clients, depending on the rules.","stop|immediately|straight away|first; check|system|inform|partner|report|transparent; decline|consent|rules|both|clients|ethic"],
   de:["Was würden Sie tun, wenn Sie einen möglichen Interessenkonflikt bemerken?","Zeig, dass du sofort und transparent handelst.","Ich würde die Arbeit an dem Mandat stoppen, es über unser Kollisionsprüfungssystem prüfen und sofort den verantwortlichen Partner informieren. Besteht ein Konflikt, lehnen wir das Mandat ab oder holen – je nach Regeln – die Zustimmung beider Mandanten ein.","stoppen|sofort|zuerst|unterbrechen; prüfen|system|informieren|partner|melden|transparent; ablehnen|zustimmung|regeln|beider|mandanten|berufsrecht"],
   fr:["Que feriez-vous si vous remarquiez un possible conflit d'intérêts ?","Montrez que vous agissez immédiatement et en toute transparence.","J'arrêterais de travailler sur le dossier, je le vérifierais dans notre système de conflits et j'informerais immédiatement l'associé responsable. S'il y a conflit, nous refusons le dossier ou obtenons, selon les règles, le consentement éclairé des deux clients.","arrêterais|immédiatement|d'abord|suspend; vérifie|système|informe|associé|signal|transparen; refus|consentement|règles|deux|clients|déontolog"]},
  {en:["How do you work with business teams who see legal as a brake?","Show partnership and practical solutions.","I get involved early and speak their language: risk, cost and time. Instead of just saying no, I explain the risk in one sentence and offer a way to reach their goal, ideally with templates they can use themselves.","early|involved|involve|partner|together; risk|cost|time|business|language|goal; instead|offer|solution|template|way|practical"],
   de:["Wie arbeiten Sie mit Fachabteilungen zusammen, die die Rechtsabteilung als Bremse sehen?","Zeig Partnerschaft und praktische Lösungen.","Ich bringe mich früh ein und spreche ihre Sprache: Risiko, Kosten und Zeit. Statt nur Nein zu sagen, erkläre ich das Risiko in einem Satz und biete einen Weg zum Ziel an – idealerweise mit Vorlagen, die sie selbst nutzen können.","früh|einbringe|einbezogen|partner|gemeinsam; risiko|kosten|zeit|geschäft|sprache|ziel; statt|biete|lösung|vorlage|weg|praktisch"],
   fr:["Comment travaillez-vous avec des équipes opérationnelles qui voient le juridique comme un frein ?","Montrez partenariat et solutions pratiques.","Je m'implique tôt et je parle leur langage : risque, coût et délai. Au lieu de dire simplement non, j'explique le risque en une phrase et je propose un moyen d'atteindre leur objectif, idéalement avec des modèles qu'ils peuvent utiliser eux-mêmes.","tôt|implique|associé|partenaire|ensemble; risque|coût|délai|métier|langage|objectif; au lieu|propose|solution|modèle|moyen|pratique"]},
  {en:["What makes a well-drafted contract in your view?","Name a few quality criteria.","It is clear, complete and as short as possible: defined terms, one idea per clause and no contradictions. A good test is whether a business reader can understand their obligations without calling a lawyer.","clear|complete|short|simple|precise; defined|terms|clause|structure|contradict|consistent; test|reader|understand|obligations|business"],
   de:["Was macht aus Ihrer Sicht einen gut formulierten Vertrag aus?","Nenne einige Qualitätskriterien.","Er ist klar, vollständig und so kurz wie möglich: definierte Begriffe, ein Gedanke pro Klausel und keine Widersprüche. Ein guter Test ist, ob ein Leser aus dem Geschäft seine Pflichten versteht, ohne einen Anwalt anzurufen.","klar|vollständig|kurz|einfach|präzise; definiert|begriffe|klausel|struktur|widerspr|einheitlich; test|leser|versteht|pflichten|geschäft"],
   fr:["Qu'est-ce qui fait, selon vous, un contrat bien rédigé ?","Citez quelques critères de qualité.","Il est clair, complet et aussi court que possible : des termes définis, une idée par clause et aucune contradiction. Un bon test : un lecteur opérationnel comprend-il ses obligations sans appeler un juriste ?","clair|complet|court|simple|précis; définis|termes|clause|structure|contradiction|cohérent; test|lecteur|comprend|obligations|opérationnel"]},
  {en:["How do you make sure your work delivers value for the client's money?","Show cost awareness and prioritisation.","I agree on the scope and a budget at the start and report early if it changes. I focus our time on the issues with the biggest risk and use standard templates for routine work.","scope|budget|agree|estimate|start; report|inform|early|transparent|change; focus|priorit|risk|templates|routine|efficien"],
   de:["Wie stellen Sie sicher, dass Ihre Arbeit ihr Geld für den Mandanten wert ist?","Zeig Kostenbewusstsein und Priorisierung.","Ich vereinbare zu Beginn den Umfang und ein Budget und melde früh, wenn sich etwas ändert. Unsere Zeit konzentriere ich auf die Themen mit dem größten Risiko, und für Routinearbeit nutze ich Standardvorlagen.","umfang|budget|vereinbar|schätz|beginn; melde|informier|früh|transparent|ändert; konzentrier|priorit|risiko|vorlagen|routine|effizien"],
   fr:["Comment vous assurez-vous que votre travail vaut ce qu'il coûte au client ?","Montrez sens des coûts et priorisation.","Je conviens dès le départ du périmètre et d'un budget, et je signale tôt tout changement. Je concentre notre temps sur les sujets les plus risqués et j'utilise des modèles standard pour le travail courant.","périmètre|budget|conviens|estimation|départ; signale|informe|tôt|transparen|changement; concentre|priorit|risque|modèles|courant|efficac"]}],
 exec:[
  {en:["How do you build a strong leadership team?","Name selection, alignment and development.","I look for people who complement me rather than copy me. We agree on a few shared goals and rules for how we work together, and I invest time in each person with regular one-to-ones and honest feedback.","complement|different|diverse|select|hire|people; goals|shared|rules|align|together; invest|one-to-one|feedback|develop|coach|trust"],
   de:["Wie bauen Sie ein starkes Führungsteam auf?","Nenne Auswahl, Ausrichtung und Entwicklung.","Ich suche Menschen, die mich ergänzen, nicht kopieren. Wir vereinbaren wenige gemeinsame Ziele und Regeln für die Zusammenarbeit, und ich investiere Zeit in jede Person – mit regelmäßigen Einzelgesprächen und ehrlichem Feedback.","ergänzen|unterschiedlich|vielfalt|auswahl|suche|menschen; ziele|gemeinsam|regeln|ausricht|zusammen; investiere|einzelgespräch|feedback|entwickl|coach|vertrauen"],
   fr:["Comment construisez-vous une équipe de direction solide ?","Citez sélection, alignement et développement.","Je cherche des personnes qui me complètent plutôt que de me ressembler. Nous convenons de quelques objectifs communs et de règles de fonctionnement, et j'investis du temps dans chacun avec des entretiens individuels réguliers et des retours honnêtes.","complètent|différent|diversité|sélection|cherche|personnes; objectifs|communs|règles|align|ensemble; investis|individuels|retours|développ|coach|confiance"]},
  {en:["How would you describe your leadership style?","Describe it with an example, not just adjectives.","I'm clear on direction and open on the way to get there. For example, I set the target of cutting delivery times in half, but the teams designed the solution themselves – and they were faster than I expected.","clear|direction|goal|target|vision; open|trust|teams|empower|involve|themselves; example|for example|result|faster|expected"],
   de:["Wie würden Sie Ihren Führungsstil beschreiben?","Beschreibe ihn mit einem Beispiel, nicht nur mit Adjektiven.","Ich bin klar in der Richtung und offen beim Weg dorthin. Zum Beispiel habe ich das Ziel gesetzt, die Lieferzeiten zu halbieren, aber die Teams haben die Lösung selbst entwickelt – und waren schneller, als ich erwartet hatte.","klar|richtung|ziel|vision; offen|vertrauen|teams|befähig|einbezieh|selbst; beispiel|ergebnis|schneller|erwartet"],
   fr:["Comment décririez-vous votre style de management ?","Décrivez-le avec un exemple, pas seulement des adjectifs.","Je suis clair sur la direction et ouvert sur le chemin. Par exemple, j'ai fixé l'objectif de diviser par deux les délais de livraison, mais ce sont les équipes qui ont conçu la solution – et elles ont été plus rapides que prévu.","clair|direction|objectif|cap|vision; ouvert|confiance|équipes|autonom|impliqu|elles-mêmes; exemple|résultat|rapides|prévu"]},
  {en:["How do you communicate in a crisis?","Name principles and an example.","Fast, honest and regular – even when we don't have all the answers yet. During a product recall I spoke to all employees on the first day, told them what we knew and didn't know, and gave daily updates until it was over.","fast|quick|honest|transparent|regular|early; employees|customers|team|spoke|told|updates; example|recall|crisis|daily|until"],
   de:["Wie kommunizieren Sie in einer Krise?","Nenne Grundsätze und ein Beispiel.","Schnell, ehrlich und regelmäßig – auch wenn wir noch nicht alle Antworten haben. Bei einem Produktrückruf habe ich am ersten Tag zu allen Mitarbeitenden gesprochen, gesagt, was wir wissen und was nicht, und bis zum Ende täglich informiert.","schnell|ehrlich|transparent|regelmäßig|früh; mitarbeit|kunden|team|gesprochen|gesagt|informiert; beispiel|rückruf|krise|täglich|bis"],
   fr:["Comment communiquez-vous en situation de crise ?","Citez des principes et un exemple.","Vite, honnêtement et régulièrement – même quand nous n'avons pas encore toutes les réponses. Lors d'un rappel de produit, j'ai parlé à tous les salariés dès le premier jour, dit ce que nous savions et ce que nous ignorions, et donné des points quotidiens jusqu'à la fin.","vite|rapide|honnête|transparen|régulièrement|tôt; salariés|clients|équipe|parlé|dit|points; exemple|rappel|crise|quotidien|jusqu"]},
  {en:["How would you approach entering a new market?","Describe the steps from analysis to decision.","I'd start with the customer need and the competition, then test the market with a small pilot and a local partner. Only when the pilot shows real demand would we invest in our own sales team.","customer|need|competition|analysis|research|market; pilot|test|partner|small|local; demand|data|invest|decide|scale|then"],
   de:["Wie würden Sie den Eintritt in einen neuen Markt angehen?","Beschreibe die Schritte von der Analyse bis zur Entscheidung.","Ich würde mit dem Kundenbedarf und dem Wettbewerb beginnen und den Markt dann mit einem kleinen Pilotprojekt und einem lokalen Partner testen. Erst wenn der Pilot echte Nachfrage zeigt, würden wir in einen eigenen Vertrieb investieren.","kunden|bedarf|wettbewerb|analyse|markt; pilot|test|partner|klein|lokal; nachfrage|daten|investier|entscheid|ausbau|erst"],
   fr:["Comment aborderiez-vous l'entrée sur un nouveau marché ?","Décrivez les étapes de l'analyse à la décision.","Je commencerais par le besoin client et la concurrence, puis je testerais le marché avec un petit pilote et un partenaire local. C'est seulement si le pilote montre une vraie demande que nous investirions dans notre propre force de vente.","client|besoin|concurrence|analyse|marché; pilote|test|partenaire|petit|local; demande|données|investir|décision|déploiement|seulement"]},
  {en:["How do you work with the board or supervisory board?","Show transparency, preparation and no surprises.","No surprises: I inform the chair early about bad news and prepare board papers that focus on decisions, not on reports. Between meetings I keep a regular one-to-one with the chair.","no surprises|early|inform|transparent|bad news; prepare|papers|decisions|focus|concise; chair|regular|one-to-one|between|meetings|relationship"],
   de:["Wie arbeiten Sie mit dem Vorstand oder Aufsichtsrat zusammen?","Zeig Transparenz, Vorbereitung und keine Überraschungen.","Keine Überraschungen: Schlechte Nachrichten bespreche ich früh mit dem Vorsitz, und meine Sitzungsunterlagen konzentrieren sich auf Entscheidungen statt auf Berichte. Zwischen den Sitzungen halte ich regelmäßige Einzelgespräche mit dem Vorsitzenden.","keine überraschung|früh|informier|transparent|schlechte nachricht; vorbereit|unterlagen|entscheidung|konzentrier|knapp; vorsitz|regelmäßig|einzelgespräch|zwischen|sitzung|beziehung"],
   fr:["Comment travaillez-vous avec le conseil d'administration ou de surveillance ?","Montrez transparence, préparation et absence de surprises.","Pas de surprises : j'informe tôt le président des mauvaises nouvelles et je prépare des dossiers centrés sur les décisions plutôt que sur les comptes rendus. Entre les séances, j'ai un échange régulier en tête-à-tête avec le président.","pas de surprise|tôt|informe|transparen|mauvaises nouvelles; prépare|dossiers|décisions|centrés|concis; président|régulier|tête-à-tête|entre|séances|relation"]},
  {en:["What is your view on digitalisation and AI in our business?","Give a balanced, practical view.","I see AI as a tool to free people from routine work, not as a goal in itself. I'd start with two or three use cases with a clear benefit – for example forecasting demand – and build the skills of our people at the same time.","tool|routine|free|support|people|not a goal; use case|benefit|start|pilot|forecast|example; skills|training|people|employees|same time|data"],
   de:["Wie sehen Sie Digitalisierung und KI in unserem Geschäft?","Gib eine ausgewogene, praktische Einschätzung.","Ich sehe KI als Werkzeug, das Menschen von Routinearbeit entlastet, nicht als Selbstzweck. Ich würde mit zwei, drei Anwendungsfällen mit klarem Nutzen beginnen – zum Beispiel Bedarfsprognosen – und gleichzeitig die Fähigkeiten unserer Leute aufbauen.","werkzeug|routine|entlastet|unterstützt|menschen|selbstzweck; anwendungsf|nutzen|beginnen|pilot|prognose|beispiel; fähigkeiten|schulung|leute|mitarbeit|gleichzeitig|daten"],
   fr:["Quel est votre regard sur le numérique et l'IA dans notre activité ?","Donnez un avis équilibré et pratique.","Je vois l'IA comme un outil qui libère les équipes des tâches répétitives, pas comme une fin en soi. Je commencerais par deux ou trois cas d'usage au bénéfice clair – par exemple la prévision de la demande – tout en développant les compétences de nos collaborateurs.","outil|répétitives|libère|soutien|équipes|fin en soi; cas d'usage|bénéfice|commencerais|pilote|prévision|exemple; compétences|formation|collaborateurs|en développant|données"]},
  {en:["How do you shape the culture of an organisation?","Name concrete levers, not slogans.","Culture follows what leaders do and what gets rewarded. I start with my own behaviour, celebrate the examples we want to see, and change processes that contradict our values – such as approval steps that slow everyone down.","leaders|behaviour|behavior|example|own|role model; reward|celebrate|recogni|promot; process|values|change|contradict|approval|rules"],
   de:["Wie prägen Sie die Kultur einer Organisation?","Nenne konkrete Hebel, keine Schlagworte.","Kultur folgt dem, was Führungskräfte tun und was belohnt wird. Ich beginne bei meinem eigenen Verhalten, würdige die Beispiele, die wir sehen wollen, und ändere Prozesse, die unseren Werten widersprechen – etwa Freigabeschleifen, die alle ausbremsen.","führungskräfte|verhalten|vorbild|eigenen|beispiel; belohnt|würdige|anerkenn|befördern; prozess|werte|ändere|widersprechen|freigabe|regeln"],
   fr:["Comment façonnez-vous la culture d'une organisation ?","Citez des leviers concrets, pas des slogans.","La culture suit ce que font les dirigeants et ce qui est récompensé. Je commence par mon propre comportement, je valorise les exemples que nous voulons voir et je change les processus qui contredisent nos valeurs – comme les circuits de validation qui ralentissent tout le monde.","dirigeants|comportement|exemple|propre|modèle; récompens|valorise|reconna|promo; processus|valeurs|change|contredisent|validation|règles"]}]};
